import pytest
from parking import parking_charge


def test_zero_minutes_is_free():
    assert parking_charge(0) == 0.0


def test_grace_period_fifteen_minutes_is_free():
    assert parking_charge(15) == 0.0


def test_sixteen_minutes_charges_one_hour():
    assert parking_charge(16) == 2.50


def test_sixty_minutes_charges_one_hour():
    assert parking_charge(60) == 2.50


def test_sixty_one_minutes_charges_two_hours():
    assert parking_charge(61) == 5.00


def test_seven_hours_costs_seventeen_fifty():
    assert parking_charge(420) == 17.50


def test_four_hundred_twenty_one_minutes_hits_daily_cap():
    assert parking_charge(421) == 18.00


def test_twenty_four_hours_is_capped_at_eighteen():
    assert parking_charge(1440) == 18.00


def test_negative_minutes_raises_value_error():
    with pytest.raises(ValueError):
        parking_charge(-1)


def test_more_than_twenty_four_hours_raises_value_error():
    with pytest.raises(ValueError):
        parking_charge(1441)
